package pl.zagranietyper.service;import pl.zagranietyper.model.FootballCompetitionProgressionSnapshot;import java.util.*;
public final class FootballCompetitionProgressionEngine {public Result resolve(long referenced,long home,long away,String round,List<FootballCompetitionProgressionSnapshot.Fixture>graph){var ties=graph.stream().filter(f->Objects.equals(f.round(),round)&&pair(f,home,away)&&Set.of("FT","AET","PEN").contains(f.status())).sorted(Comparator.comparing(FootballCompetitionProgressionSnapshot.Fixture::kickoff,Comparator.nullsLast(String::compareTo)).thenComparingLong(FootballCompetitionProgressionSnapshot.Fixture::fixtureId)).toList();if(ties.isEmpty()||ties.stream().noneMatch(f->f.fixtureId()==referenced))return unsupported(Reason.TIE_NOT_IDENTIFIED);if(ties.size()>2)return unsupported(Reason.AMBIGUOUS);if(ties.size()==1){var f=ties.get(0);Long pen=penaltyWinner(f);if(pen!=null)return new Result(pen,Proof.PENALTIES,ties,Reason.RESOLVED);if(f.goalsHome()==null||f.goalsAway()==null||Objects.equals(f.goalsHome(),f.goalsAway()))return unsupported(Reason.INCOMPLETE);long w=f.goalsHome()>f.goalsAway()?f.homeId():f.awayId();Boolean flag=Objects.equals(w,f.homeId())?f.homeWinner():f.awayWinner();Boolean loser=Objects.equals(w,f.homeId())?f.awayWinner():f.homeWinner();if(Boolean.FALSE.equals(flag)||Boolean.TRUE.equals(loser))return unsupported(Reason.INCONSISTENT);return new Result(w,Proof.SINGLE_LEG,ties,Reason.RESOLVED);}int h=0,a=0;for(var f:ties){if(f.goalsHome()==null||f.goalsAway()==null)return unsupported(Reason.INCOMPLETE);if(Objects.equals(f.homeId(),home)){h+=f.goalsHome();a+=f.goalsAway();}else{h+=f.goalsAway();a+=f.goalsHome();}}if(h!=a)return new Result(h>a?home:away,Proof.AGGREGATE,ties,Reason.RESOLVED);Long pen=penaltyWinner(ties.get(ties.size()-1));return pen==null?unsupported(Reason.AMBIGUOUS):new Result(pen,Proof.PENALTIES,ties,Reason.RESOLVED);}private static boolean pair(FootballCompetitionProgressionSnapshot.Fixture f,long a,long b){return Objects.equals(f.homeId(),a)&&Objects.equals(f.awayId(),b)||Objects.equals(f.homeId(),b)&&Objects.equals(f.awayId(),a);}private static Long penaltyWinner(FootballCompetitionProgressionSnapshot.Fixture f){if(f.penHome()==null||f.penAway()==null||Objects.equals(f.penHome(),f.penAway()))return null;return f.penHome()>f.penAway()?f.homeId():f.awayId();}private static Result unsupported(Reason r){return new Result(null,null,List.of(),r);}public enum Proof{SINGLE_LEG,AGGREGATE,PENALTIES,PROGRESSION}public enum Reason{RESOLVED,TIE_NOT_IDENTIFIED,INCOMPLETE,AMBIGUOUS,INCONSISTENT}public record Result(Long advancingTeam,Proof proof,List<FootballCompetitionProgressionSnapshot.Fixture>fixtures,Reason reason){public Result{fixtures=List.copyOf(fixtures);}public boolean resolved(){return reason==Reason.RESOLVED;}}}
